import{_ as l,a0 as o,w as r,s as d,ao as p,I as n,a1 as a,A as e,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT x X-CMD","titleTemplate":false,"description":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210520 Make your API better with this positional trick from Python 3.8","title":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好","tag":"202106","desc":""},"relativePath":"202106/20210520 Make your API better with this positional trick from Python 3.8.md","filePath":"[post].md"}'),h={name:"202106/20210520 Make your API better with this positional trick from Python 3.8.md"};function u(g,s,k,b,c,f){const t=o("Link");return r(),d("div",null,[s[19]||(s[19]=p('<h1 id="用-python-3-8-中的这个位置技巧让你的-api-变得更好" tabindex="-1">用 Python 3.8 中的这个位置技巧让你的 API 变得更好 <a class="header-anchor" href="#用-python-3-8-中的这个位置技巧让你的-api-变得更好" aria-label="Permalink to “用 Python 3.8 中的这个位置技巧让你的 API 变得更好”">​</a></h1><blockquote><p>探索只接受位置参数和其他两个未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/07/164929k51eccocxkx4xf11.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章的第九篇。Python 3.8 于 2019 年首次发布，两年后，它的许多很酷的新特性仍然没有被使用。下面是其中的三个。</p><h3 id="importlib-metadata" tabindex="-1">importlib.metadata <a class="header-anchor" href="#importlib-metadata" aria-label="Permalink to “importlib.metadata”">​</a></h3>',5)),n("p",null,[a(t,{href:"https://packaging.python.org/specifications/entry-points/"},{default:e(()=>[...s[0]||(s[0]=[i("入口点",-1)])]),_:1}),s[2]||(s[2]=i(" 在 Python 包中被用来做各种事情。大多数人熟悉的是 ",-1)),a(t,{href:"https://python-packaging.readthedocs.io/en/latest/command-line-scripts.html"},{default:e(()=>[...s[1]||(s[1]=[i("console_scripts",-1)])]),_:1}),s[3]||(s[3]=i(" 入口点，不过 Python 中的许多插件系统都使用它们。",-1))]),s[20]||(s[20]=p(`<p>在 Python 3.8 之前，从 Python 中读取入口点的最好方法是使用 <code>pkg_resources</code>，这是一个有点笨重的模块，它是 <code>setuptools</code> 的一部分。</p><p>新的 <code>importlib.metadata</code> 是一个内置模块，它允许访问同样的东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from importlib import metadata as importlib_metadata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>distribution = importlib_metadata.distribution(&quot;numpy&quot;)</span></span>
<span class="line"><span>distribution.entry_points</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    [EntryPoint(name=&#39;f2py&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3.9&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;)]</span></span></code></pre></div><p>入口点并不是 <code>importlib.metadata</code> 允许访问的唯一东西。可以调试、报告，或者（在极端情况下）触发兼容模式，你也可以在运行时检查依赖的版本！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>f&quot;{distribution.metadata[&#39;name&#39;]}=={distribution.version}&quot;\`[/code] [code]\`    &#39;numpy==1.20.1&#39;</span></span></code></pre></div><h3 id="只接受位置参数" tabindex="-1">只接受位置参数 <a class="header-anchor" href="#只接受位置参数" aria-label="Permalink to “只接受位置参数”">​</a></h3><p>强制关键字的参数在传达 API 作者的意图方面取得巨大成功之后，另一个空白被填补了：只接受位置参数。</p><p>特别是对于那些允许使用任意关键字的函数（例如，生成数据结构），这意味着对允许的参数名称的限制更少：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def some_func(prefix, /, **kwargs):</span></span>
<span class="line"><span>    print(prefix, kwargs)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>some_func(&quot;a_prefix&quot;, prefix=&quot;prefix keyword value&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   a_prefix {&#39;prefix&#39;: &#39;prefix keyword value&#39;}\`</span></span></code></pre></div><p>注意，令人困惑的是，<em>变量</em> <code>prefix</code> 的值与 <code>kwargs[&quot;prefix&quot;]</code> 的值不同。就像在很多地方一样，要注意小心使用这个功能。</p><h3 id="自我调试表达式" tabindex="-1">自我调试表达式 <a class="header-anchor" href="#自我调试表达式" aria-label="Permalink to “自我调试表达式”">​</a></h3><p>50 多年来，<code>print()</code> 语句（及其在其他语言中的对应语句）一直是快速调试输出的最爱。</p><p>但是我们在打印语句方面取得了很大的进展，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>special_number = 5</span></span>
<span class="line"><span>print(&quot;special_number = %s&quot; % special_number)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    special_number = 5</span></span></code></pre></div><p>然而，自我记录的 f-strings 使它更容易明确：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(f&quot;{special_number=}&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    special_number=5\`</span></span></code></pre></div><p>在 f-string 插值部分的末尾添加一个 <code>=</code>，可以保留字面部分，同时添加数值。</p><p>当更复杂的表达式在该部分内时，这就更有用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>values = {}</span></span>
<span class="line"><span>print(f&quot;{values.get(&#39;something&#39;, &#39;default&#39;)=}&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    values.get(&#39;something&#39;, &#39;default&#39;)=&#39;default&#39;</span></span></code></pre></div><h3 id="欢迎来到-2019-年" tabindex="-1">欢迎来到 2019 年 <a class="header-anchor" href="#欢迎来到-2019-年" aria-label="Permalink to “欢迎来到 2019 年”">​</a></h3><p>Python 3.8 大约在两年前发布，它的一些新特性非常酷，而且没有得到充分利用。如果你还没使用，那么将他们添加到你的工具箱中。</p><hr>`,28)),n("p",null,[s[5]||(s[5]=i("via: ",-1)),a(t,{href:"https://opensource.com/article/21/5/python-38-features"},{default:e(()=>[...s[4]||(s[4]=[i("https://opensource.com/article/21/5/python-38-features",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("作者：",-1)),a(t,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[6]||(s[6]=[i("Moshe Zadka",-1)])]),_:1}),s[11]||(s[11]=i(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[7]||(s[7]=[i("lujun9972",-1)])]),_:1}),s[12]||(s[12]=i(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:e(()=>[...s[8]||(s[8]=[i("geekpi",-1)])]),_:1}),s[13]||(s[13]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[i("Linux中国",-1)])]),_:1}),s[18]||(s[18]=i(" 荣誉推出",-1))])])}const x=l(h,[["render",u]]);export{P as __pageData,x as default};
